def count_comfortable_pairs(L: int, R: int) -> int:
    def digit_sum(x: int) -> int:
        return sum(map(int, str(x)))

    def is_comfortable(a: int, b: int) -> bool:
        return a != b and b in range(a - digit_sum(a), a + digit_sum(a) + 1)

    count = 0
    for a in range(L, R + 1):
        for b in range(a + 1, R + 1):
            if is_comfortable(a, b) and is_comfortable(b, a):
                count += 1

    return count

def count_happy_primes_in_range(a: int, b: int) -> int:
    def is_prime(n: int) -> bool:
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        sqrtn = int(n**0.5) + 1
        for i in range(5, sqrtn, 6):
            if n % i == 0 or n % (i + 2) == 0:
                return False
        return True

    def end_one(n: int) -> bool:
        while n > 6:
            n = sum(int(x) * int(x) for x in str(n))
            if n == 1:
                return True
        return False

    return sum(1 for n in range(a, b) if is_prime(n) and end_one(n))

