def find_numbers_with_prime_factors_sum(val: int, nMax: int) -> list[int]:
    def primef(n: int) -> list[int]:
        i = 2
        f = []
        while i * i <= n:
            if n % i:
                i += 1
            else:
                n //= i
                f.append(i)
        if n > 1:
            f.append(n)
        return f

    result = []
    for i in range(4, nMax + 1):
        fac = primef(i)
        if len(fac) > 1 and fac[0] + fac[-1] == val:
            result.append(i)

    return result

def round_to_nearest_multiple(n: int, m: int) -> int:
    # Calculate the remainder of n divided by m
    remainder = n % m
    # Check if the remainder is exactly half of m
    if remainder == m / 2:
        return n
    # Otherwise, round n to the nearest multiple of m
    return m * round(n / m)

