def merge_and_pad(line: list[int]) -> list[int]:
    from itertools import groupby

    merged = []
    for k, g in groupby(v for v in line if v):
        g = list(g)
        n, r = divmod(len(g), 2)
        if n:
            merged.extend([k * 2] * n)
        if r:
            merged.append(k)

    return merged + [0] * (len(line) - len(merged))

def largest_divisible_subset_length(a: list[int]) -> int:
    n = len(a)
    dp = [0 for _ in range(n)]
    dp[n - 1] = 1
    for i in range(n - 2, -1, -1):
        mxm = 0
        for j in range(i + 1, n):
            if a[j] % a[i] == 0 or a[i] % a[j] == 0:
                mxm = max(mxm, dp[j])
        dp[i] = 1 + mxm
    return max(dp)

def find_min_max_with_digit_sum(l: int, d: int, x: int) -> list[int]:
