def calculate_stirling_number(n: int, k: int) -> int:
    from math import factorial as fact

    if k < 0 or k > n:
        return 'It cannot be possible!'

    # Calculate Stirling numbers of the second kind
    result = sum(
        [1, -1][i % 2] * (k - i) ** n * fact(k) // (fact(k - i) * fact(i))
        for i in range(k + 1)
    ) // fact(k)

    return result

def classify_triangle(a: int, b: int, c: int) -> int:
    x, y, z = sorted([a, b, c])
    # Check if the sides can form a triangle
    if z >= x + y:
        return 0  # Not a triangle
    # Check for a right triangle
    if z * z == x * x + y * y:
        return 2  # Right triangle
    # Check for an acute or obtuse triangle
    return 1 if z * z < x * x + y * y else 3  # Acute or Obtuse triangle

def calculate_sum_of_multiples(number: int) -> int:
    def summ(number: int, d: int) -> int:
        n = (number - 1) // d
        return n * (n + 1) * d // 2

    # Calculate the sum of multiples of 3 and 5, subtracting the multiples of 15 to avoid double counting
    return summ(number, 3) + summ(number, 5) - summ(number, 15)

def calculate_divisor_sum(num: int) -> int:
    res = 1
    i = 2
    while i * i <= num:
        if num % i == 0:
            res += i
            if i * i != num:
                res += num // i
        i += 1
    return res

def amicable_numbers_sum(limit: int) -> int:
    amicables = set()
    for num in range(2, limit + 1):
        if num in amicables:
            continue
        sum_fact = calculate_divisor_sum(num)
        sum_fact2 = calculate_divisor_sum(sum_fact)
        if num == sum_fact2 and num != sum_fact:
            amicables.add(num)
            amicables.add(sum_fact)
    return sum(amicables)

def calculate_black_cells(n: int, m: int) -> int:
    from math import gcd
    # Calculate the number of black cells using the formula
    return (n + m) - 2 + gcd(n, m)

def find_digit_power_matches(a: int, b: int) -> list:
    def dig_pow(n: int) -> int:
        # Calculate the sum of digits raised to their respective positions
        return sum(int(x) ** y for y, x in enumerate(str(n), 1))

    # Collect numbers that satisfy the property in the given range
    return [x for x in range(a, b + 1) if x == dig_pow(x)]

def calculate_tables_sum(tables: list, min_val: int, max_val: int) -> int:
    # Calculate the sum of the times tables
    return sum(tables) * (min_val + max_val) * (max_val - min_val + 1) // 2
